INSERT OR IGNORE INTO articles (slug,title,excerpt,body,category,market_id,product_id,published_at,updated_at,source_url) VALUES
('eu-electronics-ce-file','Building an EU electronics technical file','The evidence pack behind CE marking should be assembled before launch, not after a regulator asks for it.','Map each applicable law to a test report, risk assessment or design record. Keep document versions aligned with the exact product model and Declaration of Conformity.','Documentation','eu','electronics','2026-08-11','2026-08-15','https://single-market-economy.ec.europa.eu/single-market/ce-marking/manufacturers_en'),
('eu-electronics-weee','WEEE registration for electronics exporters','Producer responsibility can create separate registration and reporting work in each destination market.','Identify who is the producer under the national implementation rules. Confirm registration, reporting and financing duties before the first shipment.','Waste compliance','eu','electronics','2026-08-10','2026-08-15','https://environment.ec.europa.eu/topics/waste-and-recycling/waste-electrical-and-electronic-equipment-weee_en'),
('eu-electronics-gpsr','GPSR checks for consumer electronics','The General Product Safety Regulation adds traceability and online-offer duties around consumer products.','Review the product listing, economic operator details, safety information and recall workflow. Sector rules do not remove every general safety obligation.','Product safety','eu','electronics','2026-08-09','2026-08-15','https://eur-lex.europa.eu/eli/reg/2023/988/oj/eng'),
('eu-textiles-fibre-label','EU textile fibre labels','Prescribed fibre names and destination-language requirements turn composition data into a controlled label workflow.','Obtain reliable supplier composition data and validate mixed-fibre percentages. Review language and placement requirements for every target member state.','Labeling','eu','textiles','2026-08-08','2026-08-15','https://eur-lex.europa.eu/eli/reg/2011/1007/oj/eng'),
('eu-textiles-reach','REACH screening for apparel','Chemical restrictions can apply to dyes, finishes, metal accessories and other parts of a textile article.','Build a bill-of-materials screening process and define risk-based testing. Supplier declarations should identify the exact materials and restricted-substance list reviewed.','Chemical compliance','eu','textiles','2026-08-07','2026-08-15','https://environment.ec.europa.eu/topics/chemicals/reach-regulation_en'),
('eu-textiles-gpsr','GPSR workflow for textile sellers','Online textile offers now need a clearer connection to product identity, economic operator and safety information.','Align product listing data with physical labels and internal traceability records. Create an incident and recall process before scaling sales.','Product safety','eu','textiles','2026-08-06','2026-08-15','https://eur-lex.europa.eu/eli/reg/2023/988/oj/eng'),
('eu-fcm-declaration','EU food contact declarations of compliance','A declaration is only useful when the supporting composition and migration evidence is traceable.','Match the declaration to the material grade, intended food types and use conditions. Retain supporting test and supplier documentation for competent-authority review.','Documentation','eu','food-contact','2026-08-05','2026-08-15','https://food.ec.europa.eu/food-safety/chemical-safety/food-contact-materials/legislation_en'),
('eu-fcm-migration','Planning EU migration testing','Migration testing should reproduce foreseeable contact conditions rather than use a generic test plan.','Define food simulants, time, temperature, surface ratio and repeat-use conditions. Record why each test condition represents the marketed application.','Testing','eu','food-contact','2026-08-04','2026-08-15','https://eur-lex.europa.eu/eli/reg/2011/10/oj/eng'),
('eu-fcm-gmp','GMP records for food contact materials','Quality systems are part of compliance for food contact materials, not merely a customer requirement.','Document starting-material controls, production specifications, change management and nonconforming-product handling. The records should connect a finished lot to its inputs.','Manufacturing','eu','food-contact','2026-08-03','2026-08-15','https://food.ec.europa.eu/food-safety/chemical-safety/food-contact-materials/legislation_en'),
('us-electronics-fcc-route','Choosing the FCC authorisation route','Radio and digital devices can follow different authorisation routes depending on their functions and emissions.','Classify the device before commissioning testing. Keep the grantee, label, user manual and test report consistent with the marketed configuration.','Certification','us','electronics','2026-08-02','2026-08-15','https://www.fcc.gov/engineering-technology/laboratory-division/general/equipment-authorization'),
('us-electronics-origin','US country-of-origin marking for electronics','Origin marking should be considered during enclosure and packaging design, not at the port.','Determine the correct country of origin and check available exceptions. Make the marking conspicuous, legible and sufficiently permanent for the article.','Customs','us','electronics','2026-08-01','2026-08-15','https://www.cbp.gov/trade/rulings/informed-compliance-publications/marking-country-origin-us-imports'),
('us-electronics-prop65','Proposition 65 screening for electronic products','California exposure warnings depend on product materials, exposure pathways and listed chemicals.','Screen high-risk components and intended use before deciding whether testing or a warning assessment is needed. Document the basis for the conclusion.','Chemical compliance','us','electronics','2026-07-31','2026-08-15','https://oehha.ca.gov/proposition-65'),
('us-textiles-care-label','US care label workflow','A defensible care instruction should reflect the complete garment, decoration and trim.','Validate washing, drying, ironing and professional-care instructions through testing or reliable technical evidence. Keep the basis for the selected instruction.','Labeling','us','textiles','2026-07-30','2026-08-15','https://www.ftc.gov/business-guidance/resources/clothes-captioning-complying-care-labeling-rule'),
('us-textiles-flammability','US textile flammability review','Different textile products can fall under different flammability standards and sampling plans.','Classify the product and fabric construction before testing. Children sleepwear and general apparel require separate rule checks.','Product safety','us','textiles','2026-07-29','2026-08-15','https://www.cpsc.gov/Business--Manufacturing/Business-Education/Business-Guidance/Flammable-Fabrics-Act'),
('us-textiles-children','Certificates for children textile products','A children product certificate must identify the product, rules, test basis and responsible importer or manufacturer.','Map every applicable children product rule to an accepted laboratory report. Maintain production-lot traceability and certificate access.','Certification','us','textiles','2026-07-28','2026-08-15','https://www.cpsc.gov/Business--Manufacturing/Testing-Certification'),
('us-fcm-fcn','When a US Food Contact Notification may be needed','A new substance, supplier or intended condition of use can change the FDA regulatory basis.','Identify each substance and its intended use before assuming an existing clearance applies. Review limitations, effective notifications and exemptions.','Market access','us','food-contact','2026-07-27','2026-08-15','https://www.hfpappexternal.fda.gov/scripts/fdcc/index.cfm?set=FCN'),
('us-fcm-status-letter','Building a food contact status letter','A useful regulatory letter states the exact material, lawful basis and intended-use limitations.','Avoid generic supplier assurances. Connect the statement to formulation, food type, temperature and contact duration.','Documentation','us','food-contact','2026-07-26','2026-08-15','https://www.ecfr.gov/current/title-21/chapter-I/subchapter-B/part-174'),
('us-fcm-import','FDA import preparation for food contact articles','Import documentation should make the product identity and regulatory basis easy to understand.','Align invoices, product descriptions and supplier documentation. Keep composition and compliance evidence ready for an admissibility question.','Customs','us','food-contact','2026-07-25','2026-08-15','https://www.fda.gov/industry/import-program-food-and-drug-administration-fda'),
('uk-electronics-conformity','Choosing a UK electronics conformity route','The correct route depends on the product legislation, destination within the UK and current marking policy.','Separate Great Britain from Northern Ireland at the planning stage. Confirm marking, approved-body and declaration requirements for the exact product.','Certification','uk','electronics','2026-07-24','2026-08-15','https://www.gov.uk/guidance/using-the-ukca-marking'),
('uk-electronics-rohs','UK RoHS evidence pack','Restricted-substance compliance needs material evidence and controlled supplier changes.','Collect homogeneous-material information, declarations and risk-based test reports. Update the technical file when components or suppliers change.','Chemical compliance','uk','electronics','2026-07-23','2026-08-15','https://www.gov.uk/guidance/rohs-compliance-and-guidance'),
('uk-electronics-weee','UK WEEE producer setup','Producer status determines registration, reporting and financing duties for electrical equipment.','Confirm the producer role and equipment category before placing goods on the market. Coordinate registration and reporting with the responsible scheme.','Waste compliance','uk','electronics','2026-07-22','2026-08-15','https://www.gov.uk/guidance/electrical-and-electronic-equipment-eee-producer-responsibility'),
('uk-textiles-fibre-label','UK textile fibre labeling','Fibre composition information should match the product specification and use the permitted names.','Control label artwork from verified bill-of-materials data. Review special cases such as multi-component products and decorative fibres.','Labeling','uk','textiles','2026-07-21','2026-08-15','https://www.businesscompanion.info/en/quick-guides/goods/textile-labelling'),
('uk-textiles-reach','UK REACH checks for textile imports','Chemical restrictions should be mapped to fabrics, finishes, prints and accessories.','Use supplier evidence and risk-based testing tied to the current UK restriction list. Treat material changes as a compliance trigger.','Chemical compliance','uk','textiles','2026-07-20','2026-08-15','https://www.hse.gov.uk/reach/'),
('uk-textiles-safety','Product safety files for UK apparel','A basic safety file records foreseeable hazards, controls, testing and traceability.','Consider mechanical hazards, flammability, chemical exposure and user group. Keep the assessment linked to the marketed design.','Product safety','uk','textiles','2026-07-19','2026-08-15','https://www.gov.uk/guidance/product-safety-advice-for-businesses'),
('uk-fcm-safety','UK food contact safety assessment','The assessment should connect material composition with intended food and conditions of use.','Review migration, organoleptic effects and any specific material rules. Record the assumptions behind the compliance conclusion.','Product safety','uk','food-contact','2026-07-18','2026-08-15','https://www.food.gov.uk/business-guidance/food-contact-materials'),
('uk-fcm-traceability','Traceability for UK food contact supply chains','Traceability makes it possible to investigate a nonconformity without recalling unrelated production.','Assign material and finished-lot identifiers. Retain supplier, production and customer records that support one-step-back and one-step-forward tracing.','Documentation','uk','food-contact','2026-07-17','2026-08-15','https://www.food.gov.uk/business-guidance/food-contact-materials'),
('uk-fcm-safe-use','Safe-use instructions for food contact articles','Instructions should communicate the conditions required to keep migration within the assessed limits.','State relevant temperature, duration, food type and repeat-use limitations. Ensure claims and symbols do not imply a broader use than was assessed.','Labeling','uk','food-contact','2026-07-16','2026-08-15','https://www.food.gov.uk/business-guidance/food-contact-materials');
